CREATE TABLE music_lyrics (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, track_id UUID NOT NULL, language VARCHAR(32), type VARCHAR(32) NOT NULL, content TEXT, timing_data TEXT, source VARCHAR(64), provenance VARCHAR(256), confidence NUMERIC(5,4), created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, version BIGINT NOT NULL DEFAULT 0, CHECK(type IN ('PLAIN','TIMED_LINE','TIMED_WORD','TRANSLATION','ROMANIZATION')), CHECK(confidence IS NULL OR (confidence>=0 AND confidence<=1)), FOREIGN KEY(track_id) REFERENCES music_track(id), UNIQUE(owner_id,track_id,language,type,source));
CREATE INDEX idx_music_lyrics_track ON music_lyrics(owner_id,track_id,created_at DESC);
